export const BODY: string = "\n<p>50KB، 100KB اور 200KB تین ایسے ہدف ہیں جو فارم، نوکری کی درخواست اور ویب سائٹ پر بار بار مانگے جاتے ہیں۔ تینوں کے درمیان فرق صرف عدد کا نہیں، بلکہ تصویر کے استعمال کا بھی ہے۔</p>\n<p>چھوٹی فائل تیزی سے اپ لوڈ ہوتی ہے اور ہر فارم میں قبول ہوتی ہے، مگر اس میں تفصیل کم ہوتی ہے۔ بڑی فائل زیادہ تفصیل بچاتی ہے، مگر سست ہوتی ہے اور حد سے باہر ہو سکتی ہے۔</p>\n<p>یہ مضمون تینوں سائزوں کو ایک ہی تصویر پر آزما کر دکھاتا ہے، اور بتاتا ہے کہ کون سا سائز کس کام کے لیے درست ہے۔ کمپریس کرنے کے لیے <a href=\"/ur/tasveer-compress-karein-50kb-tak/\">50KB کمپریسر</a>، <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> یا <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">200KB کمپریسر</a> استعمال کریں۔</p>\n<h2 id=\"the-short-answer\">مختصر جواب</h2>\n<p>اگر فارم 50KB مانگے تو 50KB چنیں، اگر 200KB کی اجازت ہو تو 200KB بہتر تصویر دے گا۔ درمیان میں 100KB اکثر بہترین توازن ہے: فائل ہلکی اور تصویر تیز۔</p>\n<p>سائز کا انتخاب تصویر کی قسم پر بھی منحصر ہے۔ سادہ پس منظر والی تصویر 50KB میں بھی صاف لگتی ہے، جبکہ تفصیل والی تصویر کو 200KB چاہیے ہوتا ہے۔</p>\n<p>شک ہو تو تینوں سائز بنا کر موازنہ کریں۔ ایک منٹ کا موازنہ اندازے سے بہتر فیصلہ دیتا ہے، اور غلط سائز سے بچاتا ہے۔</p>\n<h2 id=\"what-50kb-looks-like\">50KB کیسی لگتی ہے</h2>\n<p>50KB والی تصویر چھوٹی اسکرین پر صاف لگتی ہے، خاص طور پر اگر وہ پورٹریٹ یا سادہ تصویر ہو۔ چہرہ پہچانا جاتا ہے اور رنگ درست رہتے ہیں۔</p>\n<p>لیکن بڑی اسکرین پر 50KB تصویر نرم لگنے لگتی ہے، خاص طور پر آسمان میں رنگوں کی پٹیاں اور متن کے گرد ہالہ نظر آتا ہے۔ تفصیل والی تصویر 50KB میں سب سے زیادہ متاثر ہوتی ہے۔</p>\n<p>50KB کا اصل فائدہ رفتار اور قبولیت ہے: ہر فارم اسے لیتا ہے اور ہر انٹرنیٹ پر یہ سیکنڈوں میں اپ لوڈ ہو جاتی ہے۔</p>\n<h2 id=\"what-100kb-looks-like\">100KB کیسی لگتی ہے</h2>\n<p>100KB والی تصویر 50KB سے واضح بہتر لگتی ہے، خاص طور پر بڑی اسکرین پر۔ رنگوں کی پٹیاں کم ہو جاتی ہیں اور تفصیل زیادہ بچتی ہے۔</p>\n<p>زیادہ تر ویب تصویروں کے لیے 100KB بہترین توازن ہے۔ صفحہ تیزی سے لوڈ ہوتا ہے اور تصویر بھی پیشہ ورانہ لگتی ہے، اس لیے بلاگ اور دکانوں میں یہی سائز عام ہے۔</p>\n<p>پورٹریٹ اور مصنوعات کی تصویریں 100KB میں بہت اچھی لگتی ہیں، کیونکہ ان میں تفصیل درمیانی ہوتی ہے۔ صرف بہت باریک متن یا بھیڑ والی تصویر کو زیادہ چاہیے ہوتا ہے۔</p>\n<h2 id=\"what-200kb-looks-like\">200KB کیسی لگتی ہے</h2>\n<p>200KB والی تصویر بڑی اسکرین پر بھی تیز لگتی ہے، اور اس میں رنگوں کی پٹیاں تقریباً ختم ہو جاتی ہیں۔ یہ سائز پرنٹ کے چھوٹے کام اور بڑی ویب تصویر کے لیے موزوں ہے۔</p>\n<p>200KB میں متن صاف رہتا ہے اور باریک تفصیل، جیسے بال یا پتے، نظر آتے ہیں۔ اسی لیے دستاویزات اور اسکرین شاٹ کے لیے 200KB اکثر بہتر انتخاب ہے۔</p>\n<p>لیکن 200KB ہر جگہ قبول نہیں ہوتی: کچھ فارم 100KB کی حد لگاتے ہیں، اور موبائل ڈیٹا پر 200KB والی تصویریں صفحہ سست کر دیتی ہیں۔</p>\n<h2 id=\"side-by-side\">ساتھ ساتھ: ایک ہی تصویر تین سائزوں میں</h2>\n<p>ایک ہی تصویر کو تینوں سائزوں میں دیکھنے سے فرق صاف نظر آتا ہے۔ چھوٹے پیش منظر پر تینوں ایک جیسی لگتی ہیں، مگر مکمل سائز پر 50KB نرم، 100KB صاف اور 200KB تیز نظر آتی ہے۔</p>\n<p>موازنہ کرتے وقت آسمان، چہرے کی جلد اور متن کے کنارے دیکھیں۔ یہ تین جگہیں سب سے پہلے فرق دکھاتی ہیں، اور انہی سے فیصلہ کرنا چاہیے۔</p>\n<p>موازنہ کا بہترین طریقہ یہ ہے کہ تینوں نسخے ایک ساتھ کھولیں اور زوم کر کے دیکھیں۔ جو سائز آپ کی ضرورت کے لیے کافی تیز لگے، وہی چنیں۔</p>\n<h2 id=\"file-size-and-dimensions\">فائل سائز پوری کہانی نہیں</h2>\n<p>فائل سائز کے ساتھ ابعاد بھی دیکھیں: 50KB والی 4000 پکسلز کی تصویر بڑی اسکرین پر دھندلی ہوگی، جبکہ 200KB والی 800 پکسلز کی تصویر چھوٹی اسکرین پر صاف لگے گی۔</p>\n<p>ابعاد اور فائل سائز دونوں مل کر معیار طے کرتے ہیں۔ چھوٹی فائل میں بڑے ابعاد کا مطلب ہے کہ کمپریشن نے بہت تفصیل پھینکی ہے۔</p>\n<p>اس لیے فیصلہ صرف سائز دیکھ کر نہ کریں: ابعاد بھی جانچیں اور تصویر کو اس سائز میں دیکھیں جس میں وہ دکھائی دے گی۔</p>\n<h2 id=\"which-size-for-which-job\">کون سا سائز کس کام کے لیے</h2>\n<p>نوکری کے فارم اور سرکاری درخواست کے لیے 50KB چنیں، کیونکہ وہی مانگا جاتا ہے۔ بلاگ اور سوشل میڈیا کے لیے 100KB بہترین ہے، اور پرنٹ یا دستاویز کے لیے 200KB چنیں۔</p>\n<p>پروفائل تصویر کے لیے 100KB کافی ہے، کیونکہ وہ چھوٹی دکھائی دیتی ہے۔ ہیرو تصویر کے لیے 200KB بہتر ہے، کیونکہ وہ بڑی اسکرین بھرتی ہے۔</p>\n<p>اگر حد معلوم نہ ہو تو 100KB سے شروع کریں۔ یہ اکثر ہر جگہ قبول ہوتی ہے اور معیار بھی اچھا دیتی ہے۔</p>\n<h2 id=\"format-effects\">فارمیٹ موازنے کو کیسے بدلتا ہے</h2>\n<p>WebP میں 50KB تصویر JPG کے 100KB جیسی لگ سکتی ہے، کیونکہ WebP زیادہ کارآمد ہے۔ فارمیٹ بدلنے سے وہی سائز بہتر معیار دے سکتا ہے۔</p>\n<p>PNG میں 50KB بہت کم تفصیل بچاتا ہے، اس لیے PNG تصویریں اکثر 200KB سے اوپر ہوتی ہیں۔ اسکرین شاٹ کے لیے PNG میں 200KB بھی کم پڑ سکتا ہے۔</p>\n<p>سائز چننے سے پہلے فارمیٹ بھی طے کریں: WebP چھوٹے سائز میں بہتر، JPG ہر جگہ قبول، اور PNG صرف متن کے لیے۔</p>\n<h2 id=\"loading-speed\">صفحہ لوڈ ہونے کی رفتار کا کیا ہوگا</h2>\n<p>50KB والی تصویر 200KB والی سے چار گنا تیزی سے لوڈ ہوتی ہے۔ ایک صفحے پر دس تصویریں ہوں تو فرق ڈیڑھ میگا بائٹ بنتا ہے، جو موبائل پر سیکنڈوں کا فرق ہے۔</p>\n<p>رفتار صرف لوڈنگ نہیں، صارف کا تجربہ بھی ہے۔ سست صفحے سے وزیٹر واپس چلا جاتا ہے، اس لیے ویب کے لیے چھوٹا سائز اکثر بہتر فیصلہ ہے۔</p>\n<p>لیکن رفتار کے لیے معیار قربان نہ کریں: دھندلی تصویر والا تیز صفحہ بھی صارف کو مایوس کرتا ہے۔ توازن ہی درست جواب ہے۔</p>\n<h2 id=\"decision-framework\">ایک منٹ کا فیصلہ سازی طریقہ</h2>\n<p>پہلے فارم یا پلیٹ فارم کی حد دیکھیں، پھر تصویر کی قسم دیکھیں، اور آخر میں دکھائی دینے والا سائز دیکھیں۔ یہ تین جواب مل کر درست سائز بتا دیتے ہیں۔</p>\n<p>اگر حد 50KB ہو تو بحث ختم: 50KB بنائیں۔ اگر حد 200KB ہو تو تصویر کی تفصیل دیکھیں: سادہ تصویر 100KB میں کافی ہے، تفصیل والی کو 200KB دیں۔</p>\n<p>فیصلہ لکھ لیں اور اگلی بار وہی استعمال کریں۔ ہر تصویر پر نیا فیصلہ وقت ضائع کرتا ہے، جبکہ طے شدہ اصول کام تیز کرتا ہے۔</p>\n<h2 id=\"when-to-use-100kb-instead\">50KB سے 100KB پر کب جائیں</h2>\n<p>جب 50KB تصویر میں رنگوں کی پٹیاں یا متن کا ہالہ نظر آئے تو 100KB پر جائیں۔ یہ نشانی ہے کہ کمپریشن بہت سخت ہے۔</p>\n<p>جب تصویر بڑی اسکرین پر دکھانی ہو یا پرنٹ کرنا ہو تو بھی 100KB بہتر ہے۔ چھوٹے فارم کے لیے 50KB کافی ہے، مگر دکھاوے کے لیے 100KB چاہیے۔</p>\n<p>اگر 100KB بھی کافی نہ ہو تو ابعاد جانچیں: شاید مسئلہ سائز کا نہیں، ابعاد کا ہے، اور تصویر کو بڑے ابعاد چاہییں۔</p>\n<h2 id=\"quality-vs-dimensions\">معیار بمقابلہ ابعاد: اصل توازن</h2>\n<p>فائل سائز کم کرنے کے دو طریقے ہیں: معیار کم کریں یا ابعاد کم کریں۔ ابعاد کم کرنا اکثر بہتر ہے، کیونکہ چھوٹی تصویر میں کم معیار بھی صاف لگتا ہے۔</p>\n<p>4000 پکسلز والی تصویر کو 1000 پکسلز تک چھوٹا کرنے سے فائل بہت ہلکی ہو جاتی ہے، بغیر معیار بہت کم کیے۔ اس کے برعکس، بڑے ابعاد میں معیار کم کرنے سے دھندلا پن آتا ہے۔</p>\n<p>پہلے ابعاد درست کریں، پھر معیار۔ یہ ترتیب سب سے صاف نتیجہ دیتی ہے اور فائل بھی ہلکی رہتی ہے۔</p>\n<h2 id=\"colour-banding\">رنگوں کی پٹیاں اور ان سے کیسے بچیں</h2>\n<p>رنگوں کی پٹیاں اس وقت بنتی ہیں جب آسمان یا دیوار جیسے ہموار رنگ میں کمپریشن تفصیل پھینک دے۔ ہموار رنگ اچانک سیڑھی جیسی پٹیوں میں بدل جاتا ہے۔</p>\n<p>پٹیوں سے بچنے کے لیے معیار بڑھائیں یا WebP استعمال کریں، جو ہموار رنگ بہتر سنبھالتا ہے۔ تھوڑا سا شور بھی پٹیوں کو چھپا سکتا ہے، مگر یہ آخری حل ہے۔</p>\n<p>پٹیاں سب سے زیادہ 50KB میں نظر آتی ہیں، اس لیے آسمان والی تصویر کو 100KB یا 200KB دینا بہتر ہے۔</p>\n<h2 id=\"choosing-between-the-three\">تینوں سائزوں میں سے چننے کا عملی طریقہ</h2>\n<p>تینوں سائز بنا کر انہیں اس اسکرین پر دیکھیں جس پر تصویر دکھائی دے گی۔ فون پر دیکھنی ہو تو فون پر جانچیں، کمپیوٹر پر دیکھنی ہو تو کمپیوٹر پر۔</p>\n<p>سب سے چھوٹا سائز چنیں جو آپ کی آنکھ کو کافی تیز لگے۔ اگر 50KB کافی لگے تو 100KB ضائع ہے، اور اگر 100KB دھندلا لگے تو 200KB چنیں۔</p>\n<p>یہ طریقہ ہر تصویر پر آزمائیں، کیونکہ ہر تصویر کا جواب الگ ہوتا ہے۔ سادہ تصویر چھوٹے سائز میں بھی اچھی لگتی ہے، تفصیل والی کو بڑا سائز چاہیے۔</p>\n<h2 id=\"future-proofing\">کمپریس شدہ تصویروں کو مستقبل کے لیے محفوظ کرنا</h2>\n<p>کمپریس شدہ تصویر مستقبل کے لیے محفوظ نہیں ہوتی، کیونکہ اس میں تفصیل کھو چکی ہے۔ اصل فائل الگ محفوظ رکھیں، تاکہ کل بڑا سائز چاہیے ہو تو دوبارہ بنا سکیں۔</p>\n<p>اصل کو الگ فولڈر میں تاریخ کے ساتھ رکھیں اور کمپریس شدہ نقل پر کام کریں۔ یہ عادت مستقبل کی ہر ضرورت کو آسان بنا دیتی ہے۔</p>\n<p>اگر اصل کھو جائے تو کمپریس شدہ تصویر سے بڑا سائز بنانا ممکن نہیں۔ اصل کی حفاظت ہی مستقبل کی حفاظت ہے۔</p>\n<h2 id=\"upload-speeds\">اپ لوڈ کی رفتار اور سست کنکشن</h2>\n<p>سست انٹرنیٹ پر 200KB فائل اپ لوڈ ہونے میں 50KB سے چار گنا زیادہ وقت لیتی ہے۔ دیہی علاقوں یا موبائل ڈیٹا پر یہ فرق منٹوں کا ہو سکتا ہے۔</p>\n<p>اگر آپ کو بار بار تصویریں اپ لوڈ کرنی ہوں تو چھوٹا سائز چنیں۔ وقت کی بچت معیار کے ہلکے فرق سے زیادہ اہم ہوتی ہے، خاص طور پر جب تصویر چھوٹی دکھانی ہو۔</p>\n<p>اپ لوڈ سے پہلے فائل کا سائز جانچیں، تاکہ فارم کی حد سے باہر ہونے پر دوبارہ کمپریس نہ کرنا پڑے۔</p>\n<h2 id=\"printing-50kb\">کیا 50KB تصویر پرنٹ ہو سکتی ہے؟</h2>\n<p>چھوٹا پرنٹ، جیسے پاسپورٹ سائز، 50KB سے بھی بن سکتا ہے، اگر ابعاد کافی ہوں۔ لیکن بڑا پرنٹ 50KB سے دھندلا ہوگا، کیونکہ تفصیل کم ہے۔</p>\n<p>پرنٹ کے لیے ابعاد اہم ہیں، فائل سائز نہیں۔ 50KB والی 2000 پکسلز کی تصویر چھوٹے پرنٹ میں صاف نکل سکتی ہے، جبکہ 200KB والی 500 پکسلز کی تصویر نہیں۔</p>\n<p>پرنٹ سے پہلے ابعاد اور ڈی پی آئی دونوں جانچیں۔ صرف فائل سائز دیکھ کر پرنٹ کا فیصلہ نہ کریں۔</p>\n<h2 id=\"accessibility\">رسائی: کمپریس شدہ تصویریں سب کے لیے کام کریں</h2>\n<p>کمپریس شدہ تصویر بھی سب کے لیے قابل رسائی ہونی چاہیے: اس کا alt متن لکھیں، تاکہ اسکرین ریڈر استعمال کرنے والے سمجھ سکیں کہ تصویر میں کیا ہے۔</p>\n<p>متن والی تصویر کو اتنا کمپریس نہ کریں کہ متن ناقابل خواندگی ہو جائے۔ کم بینائی والے صارفین کے لیے متن کی وضاحت سب سے اہم ہے۔</p>\n<p>رنگوں کی پٹیاں بھی رسائی کا مسئلہ ہیں، کیونکہ وہ تصویر کو سمجھنا مشکل بنا دیتی ہیں۔ معیار اتنا رکھیں کہ تصویر سب کو صاف نظر آئے۔</p>\n<p>سائز کے انتخاب میں مدد کے لیے <a href=\"/ur/blog/tasveer-50kb-tak-compress-karein-rehnumai/\">50KB تک کمپریس کرنے کا رہنما</a> اور عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-50kb-tak-kaise-compress-karein/\">تصویر کو 50KB تک کیسے کمپریس کریں</a> پڑھیں۔ اپنی مرضی کا ہدف چاہیے ہو تو <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">ٹارگٹ فائل سائز کمپریسر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا 100KB 50KB سے دو گنا بہتر ہوتی ہے؟","answer":"نہیں، فرق دو گنا نہیں ہوتا۔ 100KB تصویر 50KB سے واضح بہتر لگتی ہے، خاص طور پر بڑی اسکرین پر، مگر بہتری آنکھ سے محسوس ہوتی ہے، عدد سے نہیں۔"},{"question":"کیا پورٹل بتا سکتا ہے کہ میری تصویر 50KB کی جگہ 51KB ہے؟","answer":"جی ہاں، پورٹل فائل کا درست سائز پڑھتا ہے اور 51KB کو حد سے باہر مان کر مسترد کر دیتا ہے۔ ہمیشہ حد سے تھوڑا نیچے رہیں، جیسے 49KB۔"},{"question":"لنکڈ ان پروفائل تصویر کے لیے کون سا سائز استعمال کروں؟","answer":"100KB بہترین ہے، کیونکہ پروفائل تصویر چھوٹی دکھائی دیتی ہے مگر پیشہ ورانہ لگنی چاہیے۔ 50KB بھی چل جاتی ہے، مگر 100KB میں چہرہ زیادہ تیز نظر آتا ہے۔"},{"question":"کیا بڑی فائل کا مطلب ہمیشہ بہتر نظر آنے والی تصویر ہے؟","answer":"نہیں، بڑی فائل اکثر خراب کمپریشن یا غیر ضروری میٹا ڈیٹا کی وجہ سے بڑی ہوتی ہے۔ درست ابعاد اور اچھا فارمیٹ بڑی فائل سے زیادہ اہم ہیں۔"},{"question":"میرا اسکرین شاٹ 50KB میں پورٹریٹ سے خراب کیوں لگتا ہے؟","answer":"اسکرین شاٹ میں تیز کنارے اور متن ہوتا ہے، جو کمپریشن سے سب سے زیادہ خراب ہوتا ہے۔ پورٹریٹ میں نرم رنگ ہوتے ہیں، جو آسانی سے کمپریس ہوتے ہیں۔ اسکرین شاٹ کو 100KB یا 200KB دیں۔"},{"question":"اگر فارم 200KB کی اجازت دے تو کیا 50KB استعمال کرنے کی کوئی وجہ ہے؟","answer":"جی ہاں، رفتار اور موبائل ڈیٹا۔ 50KB تیزی سے اپ لوڈ ہوتی ہے اور صفحہ ہلکا رکھتی ہے۔ اگر تصویر چھوٹی دکھانی ہو تو 50KB کافی ہے، 200KB ضائع ہے۔"}];
